static FIXTURE_COUNTER:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
use std::{path::PathBuf,process::Command,io::Read};
struct Fixture{directory:PathBuf,db:PathBuf}
impl Fixture{fn new()->Self{let directory=std::env::temp_dir().join(format!("fitig-sitemap-cli-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),FIXTURE_COUNTER.fetch_add(1,std::sync::atomic::Ordering::SeqCst)));std::fs::create_dir(&directory).unwrap();let db=directory.join("legacy.sqlite");{let c=rusqlite::Connection::open(&db).unwrap();c.execute_batch("CREATE TABLE pages(url TEXT PRIMARY KEY,json TEXT NOT NULL);CREATE TABLE frontier(url TEXT PRIMARY KEY,depth INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending');CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT);INSERT INTO metadata VALUES('seed','https://e.test/');").unwrap();for index in 0..3{let page=fitig_engine::Page{url:format!("https://e.test/שלום-{index}"),status:200,content_type:"text/html".into(),..Default::default()};c.execute("INSERT INTO pages VALUES(?1,?2)",rusqlite::params![page.url,serde_json::to_string(&page).unwrap()]).unwrap();}}Self{directory,db}}}
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.directory);}}
#[test]fn cli_creates_gzip_index_package_without_migrating_legacy_source(){let fixture=Fixture::new();let output=fixture.directory.join("sitemap.zip");let before=std::fs::read(&fixture.db).unwrap();let result=Command::new(env!("CARGO_BIN_EXE_fitig-engine")).args(["export-sitemap-package","--db",fixture.db.to_str().unwrap(),"--out",output.to_str().unwrap(),"--public-base","https://e.test/","--max-urls","1","--gzip","--lastmod"]).output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let summary:serde_json::Value=serde_json::from_slice(&result.stdout).unwrap();assert_eq!(summary["eligible_urls"],3);assert_eq!(summary["parts"].as_array().unwrap().len(),3);assert_eq!(summary["lastmod_omitted"],3);let mut archive=zip::ZipArchive::new(std::fs::File::open(output).unwrap()).unwrap();let mut png=Vec::new();archive.by_name("sitemap-00001.xml.gz").unwrap().read_to_end(&mut png).unwrap();let mut xml=String::new();flate2::read::GzDecoder::new(png.as_slice()).read_to_string(&mut xml).unwrap();assert!(xml.contains("שלום"));assert_eq!(fitig_engine::sitemaps::parse(&xml).unwrap().1.len(),1);assert!(std::fs::read(&fixture.db).unwrap()==before);}
#[test]fn cli_invalid_origin_preserves_existing_archive_and_source(){let fixture=Fixture::new();let output=fixture.directory.join("preserve.zip");std::fs::write(&output,b"previous export").unwrap();let before=std::fs::read(&fixture.db).unwrap();let result=Command::new(env!("CARGO_BIN_EXE_fitig-engine")).args(["export-sitemap-package","--db",fixture.db.to_str().unwrap(),"--out",output.to_str().unwrap(),"--public-base","https://other.test/"]).output().unwrap();assert!(!result.status.success());assert_eq!(std::fs::read(output).unwrap(),b"previous export");assert!(std::fs::read(&fixture.db).unwrap()==before);}
